//! Independent published upstream outputs, never generated by this candidate.
//! Fixed before the first comparison: raw option tolerance 1e-3 + 1e-4*|ref|;
//! action tolerance 1e-2 + 1e-4*|ref| (action logits have magnitude ~4000).
//! These criteria are for Laya; existing Vega tolerances remain untouched.
use candle::{DType, Tensor};
use candle_nn::VarBuilder;
use decapod_laya_infer::{Model, backbone_config, device};
use serde_json::Value;

use std::path::PathBuf;
use std::time::Instant;

mod support;

fn tensor(rows: &Value, device: &candle::Device) -> candle::Result<Tensor> {
    let rows: Vec<Vec<u32>> = rows
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            row.as_array()
                .unwrap()
                .iter()
                .map(|value| match value {
                    Value::Bool(value) => u32::from(*value),
                    value => u32::try_from(value.as_u64().unwrap()).unwrap(),
                })
                .collect()
        })
        .collect();
    let shape = (rows.len(), rows[0].len());
    Tensor::from_vec(
        rows.into_iter().flatten().collect::<Vec<_>>(),
        shape,
        device,
    )
}

fn compare(actual: &Tensor, expected: &Value, absolute: f32) -> candle::Result<f32> {
    let actual = actual.to_vec2::<f32>()?;
    let expected: Vec<Vec<f32>> = serde_json::from_value(expected.clone()).unwrap();
    assert_eq!(actual.len(), expected.len());
    let mut maximum = 0.0_f32;
    for (row, reference) in actual.iter().zip(&expected) {
        assert_eq!(row.len(), reference.len());
        for (actual, expected) in row.iter().zip(reference) {
            let error = (actual - expected).abs();
            assert!(actual.is_finite() && expected.is_finite());
            assert!(
                error <= absolute + 1e-4 * expected.abs(),
                "{actual} != {expected}; error={error}"
            );
            maximum = maximum.max(error);
        }
    }
    Ok(maximum)
}

fn run(metal: bool) -> Result<(), Box<dyn std::error::Error>> {
    let profile = support::profile();
    let directory = PathBuf::from(std::env::var("DECAPOD_LAYA_REFERENCE_MODEL")?);
    let path = directory.join("model.safetensors");
    profile.verify(&directory)?;
    let config = backbone_config(&std::fs::read(directory.join("encoder-config.json"))?)?;
    let reference = profile.reference;
    let device = device(metal)?;
    let start = Instant::now();
    // Immutable independently hashed checkpoint, private external fixture.
    let vb = unsafe { VarBuilder::from_mmaped_safetensors(&[path], DType::F32, &device)? };
    let model = Model::load(vb, &config, 2, profile.max_len)?;
    device.synchronize()?;
    let load_ms = start.elapsed().as_secs_f64() * 1000.0;
    let batch = &reference["batch"];
    let ids = tensor(&batch["input_ids"], &device)?;
    let mask = tensor(&batch["attention_mask"], &device)?;
    let positions = tensor(&batch["marker_pos"], &device)?;
    let marker_mask = tensor(&batch["marker_mask"], &device)?;
    let kinds: Vec<u32> = serde_json::from_value(batch["qtype"].clone())?;
    let kinds = Tensor::from_vec(kinds.clone(), kinds.len(), &device)?;
    let start = Instant::now();
    let output = model.forward(&ids, &mask, &positions, &marker_mask, &kinds)?;
    device.synchronize()?;
    let compute_ms = start.elapsed().as_secs_f64() * 1000.0;
    let option_error = compare(&output.logits, &reference["logits"], 1e-3)?;
    let action_error = compare(&output.action_logits, &reference["act_logits"], 1e-2)?;
    eprintln!(
        "backend={device:?} load_ms={load_ms:.3} synchronized_compute_ms={compute_ms:.3} option_max_error={option_error} action_max_error={action_error}"
    );
    Ok(())
}

#[test]
#[ignore = "requires the independently pinned external Laya weights"]
fn cpu_matches_published_upstream_logits() -> Result<(), Box<dyn std::error::Error>> {
    run(false)
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[test]
#[ignore = "requires actual Apple Metal and independently pinned external Laya weights"]
fn metal_matches_published_upstream_logits() -> Result<(), Box<dyn std::error::Error>> {
    run(true)
}

/// Pinned SDK `laya-rust/tests/golden/multilingual/case_long_exact_limit.json`.
/// The producer supplies calibrated answers, not intermediate tensors/raw
/// logits. This extends Metal answer comparisons to this 760-state-token
/// example; it does not establish all-input or full-limit equivalence.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[test]
#[ignore = "requires actual Metal and the independently pinned multilingual checkpoint"]
fn metal_matches_published_long_calibrated_answers() -> Result<(), Box<dyn std::error::Error>> {
    use decapod_laya_infer::laya_assets;
    use laya::{Calibration, HfTokenizer, LayaConfig, Question, SequenceBuilder};
    assert_eq!(
        std::env::var("DECAPOD_LAYA_REFERENCE_PROFILE")?,
        "multilingual"
    );
    let raw = include_bytes!("fixtures/multilingual-long-exact.json");
    assert_eq!(
        laya_assets::hash(raw),
        "sha256:8c4eb0fb6d6e87f5e7efc27cded4e475e72def9184cd8b5b516d356af704ec9a"
    );
    let reference: Value = serde_json::from_slice(raw)?;
    assert_eq!(reference["state_tokens"], 760);
    assert_eq!(reference["result"]["usage"]["state_tokens_dropped"], 0);
    assert_eq!(reference["result"]["usage"]["truncated"], false);
    let directory = PathBuf::from(std::env::var("DECAPOD_LAYA_REFERENCE_MODEL")?);
    support::profile().verify(&directory)?;
    let tokenizer =
        HfTokenizer::from_file_with_config(directory.join("onnx/tokenizer.json"), None)?;
    let calibration = LayaConfig::load(directory.join("onnx/rl_agent_config.json"))?;
    let config = backbone_config(&std::fs::read(directory.join("encoder-config.json"))?)?;
    let device = device(true)?;
    let vb = unsafe {
        VarBuilder::from_mmaped_safetensors(
            &[directory.join("model.safetensors")],
            DType::F32,
            &device,
        )?
    };
    let model = Model::load(vb, &config, 2, 1024)?;
    let start = Instant::now();
    let mut input_tokens = 0;
    for (id, item) in reference["questions"].as_object().unwrap() {
        let criteria = &item["criteria"];
        let question = match item["type"].as_str().unwrap() {
            "choice" => Question::choice(
                item["instructions"].clone(),
                criteria
                    .as_object()
                    .unwrap()
                    .iter()
                    .map(|(k, v)| (k.clone(), v.clone())),
            )?,
            "score" => Question::score(
                item["instructions"].clone(),
                criteria.as_array().unwrap().clone(),
            )?,
            "noul" => Question::noul(
                item["instructions"].clone(),
                criteria["false"].clone(),
                criteria["true"].clone(),
            ),
            _ => unreachable!(),
        };
        let (ids, markers) = SequenceBuilder::build(
            &tokenizer,
            &reference["state"],
            &question,
            calibration.max_len,
            calibration.head_max_len,
            false,
        )?;
        assert!(ids.len() >= 760 && ids.len() <= 1024);
        input_tokens += ids.len();
        let ids = Tensor::from_slice(&ids, (1, ids.len()), &device)?;
        let mask = Tensor::ones(ids.shape(), DType::U32, &device)?;
        let markers = markers
            .iter()
            .map(|i| u32::try_from(*i))
            .collect::<Result<Vec<_>, _>>()?;
        let positions = Tensor::from_slice(&markers, (1, markers.len()), &device)?;
        let valid = Tensor::ones(positions.shape(), DType::U32, &device)?;
        let kinds = Tensor::new(&[question.question_type() as u32], &device)?;
        let result = model.forward(&ids, &mask, &positions, &valid, &kinds)?;
        device.synchronize()?;
        let logits = result.logits.to_vec2::<f32>()?;
        let temperature =
            Calibration::resolve_temperature(&calibration, question.question_type(), markers.len());
        let p = Calibration::probabilities(&logits[0], markers.len(), temperature);
        let expected = &reference["result"]["answers"][id];
        let close = |a: f64, b: f64| assert!((a - b).abs() <= 1e-4, "{id}: {a} != {b}");
        match &question {
            Question::Choice(q) => {
                let labels = q.labels().collect::<Vec<_>>();
                assert_eq!(
                    labels[Calibration::arg_max(&p)],
                    expected["choice"].as_str().unwrap()
                );
                for (label, probability) in labels.iter().zip(&p) {
                    close(
                        Calibration::round4(*probability),
                        expected["probabilities"][label].as_f64().unwrap(),
                    );
                }
            }
            Question::Score(_) => close(
                Calibration::round4(Calibration::expected_score(&p)),
                expected["score"].as_f64().unwrap(),
            ),
            Question::Noul(_) => close(
                Calibration::round4(p[1]),
                expected["noul"].as_f64().unwrap(),
            ),
        }
        let action = result.action_logits.to_vec2::<f32>()?;
        close(
            Calibration::round4(Calibration::softmax(&action[0])[0]),
            expected["action"]["act_probability"].as_f64().unwrap(),
        );
    }
    assert_eq!(
        input_tokens as u64,
        reference["result"]["usage"]["input_tokens"]
            .as_u64()
            .unwrap()
    );
    eprintln!(
        "backend=metal published_state_tokens=760 questions=3 total_input_tokens={input_tokens} synchronized_compute_ms={}",
        start.elapsed().as_secs_f64() * 1000.0
    );
    Ok(())
}
